#!/usr/bin/env python3
"""Offline campaign entry point: targets, capture census, follow-up certificate.

Reads one UTF-8 JSON campaign object on stdin and writes one JSON result object
on stdout. All addresses are documentation addresses; nothing is transmitted.
"""
import json
import os
import sys
from pathlib import Path

_HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(_HERE))
sys.path.insert(0, str(_HERE.parent / 'deps'))

INPUT_LIMIT = 64 * 1024 ** 2
FAILURES = (ValueError, TypeError, KeyError, IndexError, AttributeError,
            RecursionError, MemoryError, OSError)


def audit(job):
    """Run one whole campaign and return the complete result object."""
    from common import CaptureError, Invalid, parse_json, validate
    from gen_targets import plan
    from classify_responses import capture_records
    from census import build
    from planning import solve
    context = validate(job)
    manifest, probes, low = plan(context['leases'], context['seed'])
    records, rejected = capture_records(context, probes)
    snapshots, active = build(context, records, low, probes)
    result = solve(context, active)
    return {'manifest': manifest, 'rejected': rejected, 'snapshots': snapshots,
            'active_requests': [{'id': rid, 'active': bool(active[rid])}
                                for rid in sorted(active)],
            'plan': result}


def main():
    result = None
    try:
        raw = sys.stdin.buffer.read(INPUT_LIMIT + 1)
        if len(raw) > INPUT_LIMIT:
            raise ValueError('input byte budget')
        from common import CaptureError, Invalid, parse_json
        try:
            result = audit(parse_json(raw))
        except CaptureError:
            result = {'error': 'capture'}
        except Invalid:
            result = {'error': 'invalid'}
    except FAILURES:
        result = {'error': 'invalid'}
    text = json.dumps(result, ensure_ascii=True, separators=(',', ':'),
                      allow_nan=False)
    try:
        sys.stdout.write(text)
        sys.stdout.write('\n')
        sys.stdout.flush()
    except (BrokenPipeError, OSError):
        pass
    os._exit(0)


if __name__ == '__main__':
    main()
PYEOF
